45	            Err(errors) => {
46	                self.sink.delayed_errors(errors);
47	                T::default()
48	            }
49	        }
50	    }
51	
52	    /// Runs tasks on the engine in parallel.
53	    pub fn parallelize<P, I, T, U, F>(
54	        &mut self,
55	        iter: P,
56	        f: F,
57	    ) -> impl Iterator<Item = U> + use<P, I, T, U, F>
58	    where
59	        P: IntoIterator<IntoIter = I>,
60	        I: Iterator<Item = T>,
61	        T: Send,
62	        U: Send,
63	        F: Fn(&mut Engine, T) -> U + Send + Sync,
64	    {
65	        let Engine {
66	            world, introspector, traced, ref route, library, ..
67	        } = *self;
68	
69	        // We collect into a vector and then call `into_par_iter` instead of
70	        // using `par_bridge` because it does not retain the ordering.
71	        let work: Vec<T> = iter.into_iter().collect();
72	
73	        // Work in parallel.
74	        let mut pairs: Vec<(U, Sink)> = Vec::with_capacity(work.len());
75	        work.into_par_iter()
76	            .map(|value| {
77	                let mut sink = Sink::new();
78	                let mut engine = Engine {
79	                    world,
80	                    introspector,
81	                    traced,
82	                    sink: sink.track_mut(),
83	                    route: route.clone(),
84	                    library,
85	                };
86	                (f(&mut engine, value), sink)
87	            })
88	            .collect_into_vec(&mut pairs);
89	
90	        // Apply the subsinks to the outer sink.
91	        for (_, sink) in &mut pairs {
92	            let sink = std::mem::take(sink);
93	            self.sink.extend(
94	                sink.introspections,
95	                sink.delayed,
96	                sink.warnings,
97	                sink.values,
98	            );
99	        }
100	
101	        pairs.into_iter().map(|(output, _)| output)
102	    }
103	
104	    /// Performs an introspection on the introspector and returns its result.
105	    ///
106	    /// As a side effect, the introspection is stored in the sink. If the
107	    /// document does not converge, the recorded introspections are used to
108	    /// determine the cause of non-convergence.
109	    pub fn introspect<I>(&mut self, introspection: I) -> I::Output
110	    where
111	        I: Introspect,
112	    {
113	        let introspector = *self.introspector.access("is okay since we're recording it");
114	        let output = introspection.introspect(self, introspector);
115	        self.sink.introspection(Introspection::new(introspection));
116	        output
117	    }
118	
119	    /// Create a struct that implements [`crate::foundations::BindingGuard`].
120	    pub fn binding_guard(&'_ mut self, span: Span) -> NormalBindingGuard<'_, 'a> {
121	        NormalBindingGuard { engine: self, span }
122	    }
123	}
124	
125	/// May hold a span that is currently under inspection.
126	#[derive(Default)]
127	pub struct Traced(Option<Span>);
128	
129	impl Traced {
130	    /// Wraps a to-be-traced `Span`.
131	    ///
132	    /// Call `Traced::default()` to trace nothing.
133	    pub fn new(traced: Span) -> Self {
134	        Self(Some(traced))
135	    }
136	}
137	
138	#[comemo::track]
139	impl Traced {
140	    /// Returns the traced span _if_ it is part of the given source file or
141	    /// `None` otherwise.
142	    ///
143	    /// We hide the span if it isn't in the given file so that only results for
144	    /// the file with the traced span are invalidated.
145	    pub fn get(&self, id: FileId) -> Option<Span> {
146	        if self.0.and_then(Span::id) == Some(id) { self.0 } else { None }
147	    }
148	}
149	
150	/// A push-only sink for recorded introspections, delayed errors, warnings, and
151	/// traced values.
152	///
153	/// All tracked methods of this type are of the form `(&mut self, ..) -> ()`, so
154	/// in principle they do not need validation (though that optimization is not
155	/// yet implemented in comemo).
156	#[derive(Default, Clone)]
157	pub struct Sink {
158	    /// Introspections that were performed during compilation.
159	    introspections: EcoVec<Introspection>,
160	    /// Delayed errors: Those are errors that we can ignore until the last
161	    /// iteration. For instance, show rules may throw during earlier iterations
162	    /// because the introspector is not yet ready. We first ignore that and
163	    /// proceed with empty content and only if the error remains by the end
164	    /// of the last iteration, we promote it.
165	    delayed: EcoVec<SourceDiagnostic>,
166	    /// Warnings emitted during iteration.
167	    warnings: EcoVec<SourceDiagnostic>,
168	    /// Hashes of all warning's spans and messages for warning deduplication.
169	    warnings_set: FxHashSet<u128>,
170	    /// A sequence of traced values for a span.
171	    values: EcoVec<(Value, Option<Styles>)>,
172	}
173	
174	impl Sink {
175	    /// The maximum number of traced values.
176	    pub const MAX_VALUES: usize = 10;
177	
178	    /// Create a new empty sink.
179	    pub fn new() -> Self {
180	        Self::default()
181	    }
182	
183	    /// Get the introspections.
184	    pub fn introspections(&self) -> &[Introspection] {
185	        &self.introspections
186	    }
187	
188	    /// Get the stored delayed errors.
189	    pub fn delayed(&mut self) -> EcoVec<SourceDiagnostic> {
190	        std::mem::take(&mut self.delayed)
191	    }
192	
193	    /// Get the stored warnings.
194	    pub fn warnings(self) -> EcoVec<SourceDiagnostic> {
195	        self.warnings
196	    }
197	
198	    /// Get the values for the traced span.
199	    pub fn values(self) -> EcoVec<(Value, Option<Styles>)> {
200	        self.values
201	    }
202	
203	    /// Extend from another sink.
204	    pub fn extend_from_sink(&mut self, other: Sink) {
205	        self.extend(other.introspections, other.delayed, other.warnings, other.values);
206	    }
207	}
208	
209	#[comemo::track]
210	impl Sink {
211	    /// Trace an introspection.
212	    pub fn introspection(&mut self, introspection: Introspection) {
213	        self.introspections.push(introspection);
214	    }
215	
216	    /// Add a delayed error.
217	    pub fn delayed_error(&mut self, error: SourceDiagnostic) {
218	        self.delayed.push(error);
219	    }
220	
221	    /// Add multiple delayed errors.
222	    pub fn delayed_errors(&mut self, errors: EcoVec<SourceDiagnostic>) {
223	        self.delayed.extend(errors);
224	    }
225	
226	    /// Add a warning.
227	    pub fn warn(&mut self, warning: SourceDiagnostic) {
228	        // Check if warning is a duplicate.
229	        let hash = typst_utils::hash128(&(&warning.span, &warning.message));
230	        if self.warnings_set.insert(hash) {
231	            self.warnings.push(warning);
232	        }
233	    }
234	
235	    /// Trace a value and optionally styles for the traced span.
236	    pub fn value(&mut self, value: Value, styles: Option<Styles>) {
237	        if self.values.len() < Self::MAX_VALUES {
238	            self.values.push((value, styles));
239	        }
240	    }
241	
242	    /// Extend from parts of another sink.
243	    fn extend(
244	        &mut self,
245	        introspections: EcoVec<Introspection>,
246	        delayed: EcoVec<SourceDiagnostic>,
247	        warnings: EcoVec<SourceDiagnostic>,
248	        values: EcoVec<(Value, Option<Styles>)>,
249	    ) {
250	        self.introspections.extend(introspections);
251	        self.delayed.extend(delayed);
252	        for warning in warnings {
253	            self.warn(warning);
254	        }
255	        if let Some(remaining) = Self::MAX_VALUES.checked_sub(self.values.len()) {
256	            self.values.extend(values.into_iter().take(remaining));
257	        }
258	    }
259	}
260	
261	/// The route the engine took during compilation. This is used to detect
262	/// cyclic imports and excessive nesting.
263	pub struct Route<'a> {
264	    /// The parent route segment, if present.
265	    ///
266	    /// This is used when an engine is created from another engine.
267	    // We need to override the constraint's lifetime here so that `Tracked` is
268	    // covariant over the constraint. If it becomes invariant, we're in for a
269	    // world of lifetime pain.
270	    outer: Option<Tracked<'a, Self, <Route<'static> as Track>::Call>>,
271	    /// This is set if this route segment was inserted through the start of a
272	    /// module evaluation.
273	    id: Option<FileId>,
274	    /// This is set whenever we enter a function, nested layout, or are applying
275	    /// a show rule. The length of this segment plus the lengths of all `outer`
276	    /// route segments make up the length of the route. If the length of the
277	    /// route exceeds `MAX_DEPTH`, then we throw a "maximum ... depth exceeded"
278	    /// error.
279	    len: usize,
280	    /// The upper bound we've established for the parent chain length.
281	    ///
282	    /// We don't know the exact length (that would defeat the whole purpose
283	    /// because it would prevent cache reuse of some computation at different,
284	    /// non-exceeding depths).
285	    upper: AtomicUsize,
286	}
287	
288	impl<'a> Route<'a> {
289	    /// Create a new, empty route.
290	    pub fn root() -> Self {
291	        Self {
292	            id: None,
293	            outer: None,
294	            len: 0,
295	            upper: AtomicUsize::new(0),
296	        }
297	    }
298	
299	    /// Extend the route with another segment with a default length of 1.
300	    pub fn extend(outer: Tracked<'a, Self>) -> Self {
301	        Route {
302	            outer: Some(outer),
303	            id: None,
304	            len: 1,
305	            upper: AtomicUsize::new(usize::MAX),
306	        }
307	    }
308	
309	    /// Attach a file id to the route segment.
310	    pub fn with_id(self, id: FileId) -> Self {
311	        Self { id: Some(id), ..self }
312	    }
313	
314	    /// Set the length of the route segment to zero.
315	    pub fn unnested(self) -> Self {
316	        Self { len: 0, ..self }
317	    }
318	
319	    /// Start tracking this route.
320	    ///
321	    /// In comparison to [`Track::track`], this method skips this chain link
322	    /// if it does not contribute anything.
323	    pub fn track(&self) -> Tracked<'_, Self> {
324	        match self.outer {
325	            Some(outer) if self.id.is_none() && self.len == 0 => outer,
326	            _ => Track::track(self),
327	        }
328	    }
329	
330	    /// Increase the nesting depth for this route segment.
331	    pub fn increase(&mut self) {
332	        self.len += 1;
333	    }
334	
335	    /// Decrease the nesting depth for this route segment.
336	    pub fn decrease(&mut self) {
337	        self.len -= 1;
338	    }
339	}
340	
341	/// The maximum nesting depths. They are different so that even if show rule and
342	/// call checks are interleaved, for show rule problems we always get the show
343	/// rule error. The lower the max depth for a kind of error, the higher its
344	/// precedence compared to the others.
345	impl Route<'_> {
346	    /// The maximum stack nesting depth.
347	    const MAX_SHOW_RULE_DEPTH: usize = 64;
348	
349	    /// The maximum layout nesting depth.
350	    const MAX_LAYOUT_DEPTH: usize = 72;
351	
352	    /// The maximum HTML nesting depth.
353	    const MAX_HTML_DEPTH: usize = 72;
354	
355	    /// The maximum function call nesting depth.
356	    const MAX_CALL_DEPTH: usize = 80;
357	
358	    /// Ensures that we are within the maximum show rule depth.
359	    pub fn check_show_depth(&self) -> HintedStrResult<()> {
360	        if !self.within(Route::MAX_SHOW_RULE_DEPTH) {
361	            bail!(
362	                "maximum show rule depth exceeded";
363	                hint: "maybe a show rule matches its own output";
364	                hint: "maybe there are too deeply nested elements";
365	            );
366	        }
367	        Ok(())
368	    }
369	
370	    /// Ensures that we are within the maximum layout depth.
371	    pub fn check_layout_depth(&self) -> HintedStrResult<()> {
372	        if !self.within(Route::MAX_LAYOUT_DEPTH) {
373	            bail!(
374	                "maximum layout depth exceeded";
375	                hint: "try to reduce the amount of nesting in your layout";
376	            );
377	        }
378	        Ok(())
379	    }
380	
381	    /// Ensures that we are within the maximum HTML depth.
382	    pub fn check_html_depth(&self) -> HintedStrResult<()> {
383	        if !self.within(Route::MAX_HTML_DEPTH) {
384	            bail!(
385	                "maximum HTML depth exceeded";
386	                hint: "try to reduce the amount of nesting of your HTML";
387	            );
388	        }
389	        Ok(())
390	    }
391	
392	    /// Ensures that we are within the maximum function call depth.
393	    pub fn check_call_depth(&self) -> StrResult<()> {
394	        if !self.within(Route::MAX_CALL_DEPTH) {
395	            bail!("maximum function call depth exceeded");
396	        }
397	        Ok(())
398	    }
399	}
400	
401	#[comemo::track]
402	#[expect(clippy::elidable_lifetime_names, reason = "required for `comemo::track`")]
403	impl<'a> Route<'a> {
404	    /// Whether the given id is part of the route.
405	    pub fn contains(&self, id: FileId) -> bool {
406	        self.id == Some(id) || self.outer.is_some_and(|outer| outer.contains(id))
407	    }
408	
409	    /// Whether the route's depth is less than or equal to the given depth.
410	    pub fn within(&self, depth: usize) -> bool {
411	        // We only need atomicity and no synchronization of other operations, so
412	        // `Relaxed` is fine.
413	        use Ordering::Relaxed;
414	
415	        let upper = self.upper.load(Relaxed);
416	        if upper.saturating_add(self.len) <= depth {
417	            return true;
418	        }
419	
420	        match self.outer {
421	            Some(_) if depth < self.len => false,
422	            Some(outer) => {
423	                let within = outer.within(depth - self.len);
424	                if within && depth < upper {
425	                    // We don't want to accidentally increase the upper bound,
426	                    // hence the compare-exchange.
427	                    self.upper.compare_exchange(upper, depth, Relaxed, Relaxed).ok();
428	                }
429	                within
430	            }
431	            None => true,
432	        }
433	    }
434	}
435	
436	impl Default for Route<'_> {
437	    fn default() -> Self {
438	        Self::root()
439	    }
440	}
441	
442	impl Clone for Route<'_> {
443	    fn clone(&self) -> Self {
444	        Self {
445	            outer: self.outer,
446	            id: self.id,
447	            len: self.len,
448	            upper: AtomicUsize::new(self.upper.load(Ordering::Relaxed)),
449	        }
450	    }
451	}
